def add_questions(questions_list, category):
    created = []
    for q in questions_list:
        text, opt_a, opt_b, opt_c, correct = q
        question = Question.objects.create(
            text=text,
            option_a=opt_a,
            option_b=opt_b,
            option_c=opt_c,
            correct_answer=correct,
            created_by=teacher
        )
        created.append(question)
    print(f"{category}: добавлено {len(created)} вопросов")
    return created

